mapper.select:
SELECT risk_unit.dynamic_risk_level,
CAST(COUNT(*) AS INTEGER) AS count
FROM (
    SELECT DISTINCT t1.slope_unit_id,
    t1.dynamic_risk_level
    FROM dz_risk_assessment t1
    LEFT JOIN data_slope_unit t2
    ON t1.slope_unit_id = t2.id
    LEFT JOIN v_monitor_device t3 ON t3.slope_unit_id = t2.id
    WHERE 1 = 1


    AND t1.dynamic_risk_level IN (3, 4)
    AND t1.create_date BETWEEN #{startTime} AND #{endTime}

        AND t2.province = #{bo.province}


        AND t2.city = #{bo.city}


        AND t2.county = #{bo.county}


        AND t2.street = #{bo.street}


        AND t2.village = #{bo.village}

) risk_unit
GROUP BY risk_unit.dynamic_risk_level

SELECT risk_unit.dynamic_risk_level,
CAST(COUNT(*) AS INTEGER) AS count
FROM (
    SELECT DISTINCT t1.slope_unit_id,
    t1.dynamic_risk_level
    FROM dz_risk_assessment t1
    LEFT JOIN data_slope_unit t2 ON t1.slope_unit_id = t2.id
    WHERE 1 = 1


    AND t1.create_date BETWEEN #{startTime} AND #{endTime}

        AND t2.province = #{bo.province}


        AND t2.city = #{bo.city}


        AND t2.county = #{bo.county}


        AND t2.street = #{bo.street}


        AND t2.village = #{bo.village}

) risk_unit
GROUP BY risk_unit.dynamic_risk_level

SELECT risk_unit.dynamic_risk_level,
CAST(COUNT(DISTINCT hazard_point.id) AS INTEGER) AS count
FROM (
    SELECT DISTINCT t1.slope_unit_id,
    t1.dynamic_risk_level
    FROM dz_risk_assessment t1
    LEFT JOIN data_slope_unit t2 ON t1.slope_unit_id = t2.id
    WHERE 1 = 1


    AND t1.create_date BETWEEN #{startTime} AND #{endTime}

        AND t2.province = #{bo.province}


        AND t2.city = #{bo.city}


        AND t2.county = #{bo.county}


        AND t2.street = #{bo.street}


        AND t2.village = #{bo.village}

) risk_unit
LEFT JOIN data_hazard_point hazard_point ON hazard_point.slope_unit_id = risk_unit.slope_unit_id
GROUP BY risk_unit.dynamic_risk_level

SELECT risk_unit.dynamic_risk_level, risk_unit.areaName, CAST(COUNT(*) AS INTEGER) AS count FROM ( SELECT DISTINCT t1.slope_unit_id, t1.dynamic_risk_level,
COALESCE(t2.village, 'Unknown') COALESCE(t2.village, 'Unknown') COALESCE(t2.street, 'Unknown') COALESCE(t2.county, 'Unknown') COALESCE(t2.city, 'Unknown') COALESCE(t2.province, 'Unknown')
AS areaName FROM dz_risk_assessment t1 LEFT JOIN data_slope_unit t2 ON t1.slope_unit_id = t2.id WHERE 1 = 1
AND t1.dynamic_risk_level IN (3, 4) AND t1.create_date BETWEEN #{startTime} AND #{endTime}
AND t2.province = #{bo.province}
AND t2.city = #{bo.city}
AND t2.county = #{bo.county}
AND t2.street = #{bo.street}
AND t2.village = #{bo.village}
) risk_unit GROUP BY risk_unit.dynamic_risk_level, risk_unit.areaName

SELECT risk_unit.dynamic_risk_level,
risk_unit.suggest
FROM (
    SELECT
    t1.dynamic_risk_level,
    t1.dynamic_risk_suggest AS suggest,
    ROW_NUMBER() OVER (
        PARTITION BY t1.slope_unit_id, t1.dynamic_risk_level
        ORDER BY t1.create_date DESC, t1.id DESC
    ) AS rn
    FROM dz_risk_assessment t1
    LEFT JOIN data_slope_unit t2 ON t1.slope_unit_id = t2.id
    WHERE 1 = 1


    AND t1.dynamic_risk_level IN (3, 4)
    AND t1.create_date BETWEEN #{startTime} AND #{endTime}
    AND t1.dynamic_risk_suggest IS NOT NULL
    AND t1.dynamic_risk_suggest != ''

        AND t2.province = #{bo.province}


        AND t2.city = #{bo.city}


        AND t2.county = #{bo.county}


        AND t2.street = #{bo.street}


        AND t2.village = #{bo.village}

) risk_unit
WHERE risk_unit.rn = 1

select dsu.village name, dsu.village_code code
from (
         select t2.village,
                t2.village_code,
                count(*) count
         from dz_risk_assessment t1
                  left join data_slope_unit t2 on t1.slope_unit_id = t2.id
         where 1 = 1


           and t1.dynamic_risk_level in (3, 4)
           and t1.create_date between #{startTime} and #{endTime}

             and t2.province = #{bo.province}


             and t2.city = #{bo.city}


             and t2.county = #{bo.county}


             and t2.street = #{bo.street}


             and t2.village = #{bo.village}

         group by t2.village, t2.village_code
         order by count desc
         limit 3
     ) dsu

SELECT DATE (create_date) AS date, hazard, risk, hazard_level AS hazardLevel, risk_level AS riskLevel
FROM (
    SELECT t1.create_date, t1.hazard, t1.risk, t1.hazard_level, t1.risk_level, ROW_NUMBER() OVER (PARTITION BY DATE (t1.create_date) ORDER BY t1.create_date DESC) AS rn
    FROM dz_risk_assessment t1
    LEFT JOIN data_slope_unit t2 ON t1.slope_unit_id = t2.id
    WHERE t1.slope_unit_id = #{bo.slopeUnitId}

    AND t1.create_date BETWEEN #{startTime} AND #{endTime}
) t
WHERE rn = 1
ORDER BY date
